def parse_args():
    return {"input": "cards.json", "output": "summary.json"}
def validate_input(path):
    return path.endswith(".json")
def process(path):
    return {"source": path, "count": 3}
def save_result(result, output):
    return output
def main():
    args = parse_args()
    validate_input(args["input"])
    result = process(args["input"])
    return save_result(result, args["output"])
print(main())

